def indexed(items: list[Any], key: str | Callable[[Any], Any]) -> dict[Any, list[Any]]:
    """Build an index for a list of objects"""
    idx: dict[Any, Any] = {}
    for item in items:
        key_ = getattr(item, key) if isinstance(key, str) else key(item)
        idx.setdefault(key_, []).append(item)
    return idx

