def tables(  # pylint: disable=no-self-use
        self,
        db_id: int,
        schema: str,
        force_refresh: str = "false",
    ) -> FlaskResponse:
        """Endpoint to fetch the list of tables for given database"""

        force_refresh_parsed = force_refresh.lower() == "true"
        schema_parsed = utils.parse_js_uri_path_item(schema, eval_undefined=True)

        if not schema_parsed:
            return json_error_response(_("Schema undefined"), status=422)

        # Guarantees database filtering by security access
        database = (
            DatabaseFilter("id", SQLAInterface(Database, db.session))
            .apply(
                db.session.query(Database),
                None,
            )
            .filter_by(id=db_id)
            .one_or_none()
        )

        if not database:
            return json_error_response(
                __("Database not found: %(id)s", id=db_id), status=404
            )

        try:
            tables = security_manager.get_datasources_accessible_by_user(
                database=database,
                schema=schema_parsed,
                datasource_names=sorted(
                    utils.DatasourceName(*datasource_name)
                    for datasource_name in database.get_all_table_names_in_schema(
                        schema=schema_parsed,
                        force=force_refresh_parsed,
                        cache=database.table_cache_enabled,
                        cache_timeout=database.table_cache_timeout,
                    )
                ),
            )

            views = security_manager.get_datasources_accessible_by_user(
                database=database,
                schema=schema_parsed,
                datasource_names=sorted(
                    utils.DatasourceName(*datasource_name)
                    for datasource_name in database.get_all_view_names_in_schema(
                        schema=schema_parsed,
                        force=force_refresh_parsed,
                        cache=database.table_cache_enabled,
                        cache_timeout=database.table_cache_timeout,
                    )
                ),
            )
        except SupersetException as ex:
            return json_error_response(ex.message, ex.status)

        extra_dict_by_name = {
            table.name: table.extra_dict
            for table in (
                db.session.query(SqlaTable).filter(
                    SqlaTable.database_id == database.id,
                    SqlaTable.schema == schema_parsed,
                )
            ).all()
        }

        options = sorted(
            [
                {
                    "value": table.table,
                    "type": "table",
                    "extra": extra_dict_by_name.get(table.table, None),
                }
                for table in tables
            ]
            + [
                {
                    "value": view.table,
                    "type": "view",
                }
                for view in views
            ],
            key=lambda item: item["value"],
        )

        payload = {"tableLength": len(tables) + len(views), "options": options}
        return json_success(json.dumps(payload))

def estimate_query_cost(  # pylint: disable=no-self-use
        self, database_id: int, schema: Optional[str] = None
    ) -> FlaskResponse:
        mydb = db.session.query(Database).get(database_id)

        sql = json.loads(request.form.get("sql", '""'))
        if template_params := json.loads(request.form.get("templateParams") or "{}"):
            template_processor = get_template_processor(mydb)
            sql = template_processor.process_template(sql, **template_params)

        timeout = SQLLAB_QUERY_COST_ESTIMATE_TIMEOUT
        timeout_msg = f"The estimation exceeded the {timeout} seconds timeout."
        try:
            with utils.timeout(seconds=timeout, error_message=timeout_msg):
                cost = mydb.db_engine_spec.estimate_query_cost(
                    mydb, schema, sql, utils.QuerySource.SQL_LAB
                )
        except SupersetTimeoutException as ex:
            logger.exception(ex)
            return json_errors_response([ex.error])
        except Exception as ex:  # pylint: disable=broad-except
            return json_error_response(utils.error_msg_from_exception(ex))

        spec = mydb.db_engine_spec
        query_cost_formatters: Dict[str, Any] = app.config[
            "QUERY_COST_FORMATTERS_BY_ENGINE"
        ]
        query_cost_formatter = query_cost_formatters.get(
            spec.engine, spec.query_cost_formatter
        )
        cost = query_cost_formatter(cost)

        return json_success(json.dumps(cost))

def _import(  # pylint: disable=arguments-differ, too-many-locals, too-many-branches
        session: Session,
        configs: Dict[str, Any],
        overwrite: bool = False,
        force_data: bool = False,
    ) -> None:
        # import databases
        database_ids: Dict[str, int] = {}
        for file_name, config in configs.items():
            if file_name.startswith("databases/"):
                database = import_database(
                    session,
                    config,
                    overwrite=overwrite,
                    ignore_permissions=True,
                )
                database_ids[str(database.uuid)] = database.id

        # import datasets
        # If database_uuid is not in the list of UUIDs it means that the examples
        # database was created before its UUID was frozen, so it has a random UUID.
        # We need to determine its ID so we can point the dataset to it.
        examples_db = get_example_database()
        dataset_info: Dict[str, Dict[str, Any]] = {}
        for file_name, config in configs.items():
            if file_name.startswith("datasets/"):
                # find the ID of the corresponding database
                if config["database_uuid"] not in database_ids:
                    if examples_db is None:
                        raise Exception("Cannot find examples database")
                    config["database_id"] = examples_db.id
                else:
                    config["database_id"] = database_ids[config["database_uuid"]]

                # set schema
                if config["schema"] is None:
                    config["schema"] = get_example_default_schema()

                try:
                    dataset = import_dataset(
                        session,
                        config,
                        overwrite=overwrite,
                        force_data=force_data,
                        ignore_permissions=True,
                    )
                except MultipleResultsFound:
                    # Multiple results can be found for datasets. There was a bug in
                    # load-examples that resulted in datasets being loaded with a NULL
                    # schema. Users could then add a new dataset with the same name in
                    # the correct schema, resulting in duplicates, since the uniqueness
                    # constraint was not enforced correctly in the application logic.
                    # See https://github.com/apache/superset/issues/16051.
                    continue

                dataset_info[str(dataset.uuid)] = {
                    "datasource_id": dataset.id,
                    "datasource_type": "table",
                    "datasource_name": dataset.table_name,
                }

        # import charts
        chart_ids: Dict[str, int] = {}
        for file_name, config in configs.items():
            if (
                file_name.startswith("charts/")
                and config["dataset_uuid"] in dataset_info
            ):
                # update datasource id, type, and name
                config.update(dataset_info[config["dataset_uuid"]])
                chart = import_chart(
                    session,
                    config,
                    overwrite=overwrite,
                    ignore_permissions=True,
                )
                chart_ids[str(chart.uuid)] = chart.id

        # store the existing relationship between dashboards and charts
        existing_relationships = session.execute(
            select([dashboard_slices.c.dashboard_id, dashboard_slices.c.slice_id])
        ).fetchall()

        # import dashboards
        dashboard_chart_ids: List[Tuple[int, int]] = []
        for file_name, config in configs.items():
            if file_name.startswith("dashboards/"):
                try:
                    config = update_id_refs(config, chart_ids, dataset_info)
                except KeyError:
                    continue

                dashboard = import_dashboard(
                    session,
                    config,
                    overwrite=overwrite,
                    ignore_permissions=True,
                )
                dashboard.published = True

                for uuid in find_chart_uuids(config["position"]):
                    chart_id = chart_ids[uuid]
                    if (dashboard.id, chart_id) not in existing_relationships:
                        dashboard_chart_ids.append((dashboard.id, chart_id))

        # set ref in the dashboard_slices table
        values = [
            {"dashboard_id": dashboard_id, "slice_id": chart_id}
            for (dashboard_id, chart_id) in dashboard_chart_ids
        ]
        session.execute(dashboard_slices.insert(), values)

