        except OSError:
            raise Http404

def download_file(self, download_id, project: Project):
        ty, ty_id = download_id.split("/")

        rate_limited = ratelimits.is_limited(
            project=project,
            key=f"rl:ArtifactLookupEndpoint:download:{download_id}:{project.id}",
            limit=10,
        )
